/*
 * A042226  Numerators of continued fraction convergents to sqrt(639).
 * https://oeis.org/A042226
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy
 * Formula:   not stated
 * Range:     u8 n <= 3, u16 n <= 9, u32 n <= 17, u64 n <= 37, u128 n <= 79,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Numerators of convergents for sqrt(639).  The function
 * a(n) returns the nth numerator of the continued‑fraction
 * convergents to sqrt(639).  The terms are generated by the
 * standard recurrence
 *
 *    h_{-2}=0, h_{-1}=1
 *    h_{k}=a_k*h_{k-1}+h_{k-2}
 *
 * where a_k are the partial quotients of the continued
 * fraction of sqrt(639).  The partial quotients are produced
 * by the standard algorithm for quadratic irrationals.
 *
 * This implementation uses only integer arithmetic and
 * supports all integer sizes provided by the build.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* constants for the quadratic irrational sqrt(639) */
    const idx_t D   = 639;          /* the radicand */
    const idx_t a0  = 25;           /* floor(sqrt(639)) */

    /* variables for the continued‑fraction algorithm */
    idx_t m = 0;                    /* m_i */
    idx_t d = 1;                    /* d_i */
    idx_t a_term = a0;              /* a_i */

    /* variables for the recurrence of convergent numerators */
    seq_t h_prevprev = 0;           /* h_{-2} */
    seq_t h_prev     = 1;           /* h_{-1} */
    seq_t h_curr;                   /* h_k */

    /* iterate through n+1 convergents */
    idx_t i;
    for (i = 0; i <= n; ++i) {
        /* compute the next numerator */
        h_curr = (seq_t)a_term * h_prev + h_prevprev;

        if (i == n)
            return h_curr;

        /* shift recurrence state */
        h_prevprev = h_prev;
        h_prev     = h_curr;

        /* advance continued‑fraction terms */
        /* m_{i+1} = d_i * a_i - m_i */
        m = d * a_term - m;
        /* d_{i+1} = (D - m_{i+1}^2) / d_i */
        d = (D - m * m) / d;
        /* a_{i+1} = floor((a0 + m_{i+1}) / d_{i+1}) */
        a_term = (a0 + m) / d;
    }

    /* should never reach here */
    return 0;
}
